flow=[("18:30","Une demande de rénovation de cuisine arrive depuis le site web."),("18:31","Le client reçoit les questions clés et envoie photos et mesures."),("Jour 1","Avec toutes les informations, un brouillon de devis est préparé."),("Jour 2","Le responsable le vérifie et l'envoie avec le plan et le rendu avant/après."),("Jour 5","Sans réponse, une relance automatique part."),("Sur le chantier","Les rapports quotidiens arrivent au bureau et le client reçoit un résumé chaque semaine.")],
